int verify_asn1_signature(const ASN1_ITEM *it, X509_ALGOR *a, ASN1_BIT_STRING *signature, void *asn, EVP_PKEY *pkey) {
    EVP_MD_CTX *ctx = NULL;
    const EVP_MD *md = NULL;
    int result = -1;

    if (!it || !a || !signature || !asn || !pkey) {
        return -1;
    }

    if (!a->parameter || !EVP_PKEY_type(pkey->type)) {
        return -1;
    }

    md = EVP_get_digestbyname(OBJ_nid2ln(a->algorithm));
    if (!md) {
        return -1;
    }

    ctx = EVP_MD_CTX_new();
    if (!ctx) {
        return -1;
    }

    if (!EVP_VerifyInit_ex(ctx, md, NULL) ||
        !EVP_VerifyUpdate(ctx, asn, it->it->size(asn)) ||
        !EVP_VerifyFinal(ctx, signature->data, signature->length, pkey)) {
        result = 0;
    } else {
        result = 1;
    }

    EVP_MD_CTX_free(ctx);
    return result;
}
